/**
 * Brand Archetype quiz content.
 *
 * Design-clone content policy: the six archetype names and the UI strings are kept; every
 * question, answer and result description below is ORIGINAL placeholder copy, and the
 * imagery is the procedural low-poly placeholder set generated by
 * scripts/generate-archetype-art.mjs (public/placeholders/archetype-<slug>.svg).
 */

export type ArchetypeSlug = "creator" | "leader" | "entertainer" | "guardian" | "innovator" | "sage";

export interface Archetype {
  name: string;
  /** Result copy; the first paragraph is upright, the following ones render in italics. */
  paragraphs: string[];
  /** Result illustration (1080 x 1449 placeholder figure). */
  image: string;
}

export interface QuizAnswer {
  text: string;
  archetype: ArchetypeSlug;
}

export interface QuizQuestion {
  label: string;
  answers: QuizAnswer[];
}

/** Display / tie-break order (the order the result pages are listed in on the site). */
export const ARCHETYPE_ORDER: ArchetypeSlug[] = ["creator", "leader", "entertainer", "guardian", "innovator", "sage"];

