export function isArchetypeSlug(value: string): value is ArchetypeSlug {
  return (ARCHETYPE_ORDER as string[]).includes(value);
}

/** Archetype with the most answers; ties go to the earliest in ARCHETYPE_ORDER. */
export function scoreQuiz(answers: ArchetypeSlug[]): ArchetypeSlug {
  const tally = new Map<ArchetypeSlug, number>();
  for (const slug of answers) tally.set(slug, (tally.get(slug) ?? 0) + 1);
  let best: ArchetypeSlug = ARCHETYPE_ORDER[0];
  let bestCount = -1;
  for (const slug of ARCHETYPE_ORDER) {
    const count = tally.get(slug) ?? 0;
    if (count > bestCount) {
      best = slug;
      bestCount = count;
    }
  }
  return best;
}
